create table if not exists public.applicants(id bigint generated by default as identity primary key,application_no text not null unique,name text not null,department text,status text check(status in ('accepted','rejected','waitlist') or status is null),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.admins(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.site_settings(id integer primary key check(id=1),results_published boolean not null default false);
insert into public.site_settings(id,results_published) values(1,false) on conflict(id) do nothing;
create table if not exists public.lookup_attempts(ip_hash text primary key,window_started_at timestamptz not null default now(),attempt_count integer not null default 0);
alter table public.applicants enable row level security;alter table public.admins enable row level security;alter table public.site_settings enable row level security;alter table public.lookup_attempts enable row level security;
revoke all on public.applicants from anon,authenticated;revoke all on public.admins from anon,authenticated;revoke all on public.site_settings from anon,authenticated;revoke all on public.lookup_attempts from anon,authenticated;
create or replace function public.record_lookup_attempt(p_ip_hash text) returns integer language plpgsql security definer set search_path=public as $$ declare current_count integer; begin insert into public.lookup_attempts(ip_hash,window_started_at,attempt_count) values(p_ip_hash,now(),1) on conflict(ip_hash) do update set attempt_count=case when lookup_attempts.window_started_at<now()-interval '10 minutes' then 1 else lookup_attempts.attempt_count+1 end,window_started_at=case when lookup_attempts.window_started_at<now()-interval '10 minutes' then now() else lookup_attempts.window_started_at end returning attempt_count into current_count;return current_count;end;$$;
revoke all on function public.record_lookup_attempt(text) from public;grant execute on function public.record_lookup_attempt(text) to service_role;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end;$$;
drop trigger if exists applicants_updated_at on public.applicants;
create trigger applicants_updated_at before update on public.applicants for each row execute function public.set_updated_at();